import subprocess,os,time,base64,io,tarfile
F={'setup_env.sh': '#!/bin/bash\n# Kaggle (Ubuntu 24.04, T4) reproduction of hackathon/docker/Dockerfile without Docker:\n#  - NVIDIA user-space graphics libs matching the host kernel driver (Vulkan ICD)\n#  - Isaac Sim 5.0 + Isaac Lab 2.2 (pip, python 3.11, micromamba env "isaac")\n#  - ROS 2 Humble from RoboStack (micromamba env "ros") + bodyctrl_msgs rebuilt from the organiser .deb\'s own .msg/.srv\nset -x\nW=/kaggle/working; T=/tmp/w; mkdir -p $T $W/logs; cd $T\nexport MAMBA_ROOT_PREFIX=$T/mm\nnvidia-smi --query-gpu=name,driver_version --format=csv,noheader | tee $W/logs/gpu.txt\nDRV=$(nvidia-smi --query-gpu=driver_version --format=csv,noheader | head -1 | tr -d \' \')\n# 1) driver user-space (graphics) libs of exactly the host version\ncurl -sfL -o drv.run https://download.nvidia.com/XFree86/Linux-x86_64/$DRV/NVIDIA-Linux-x86_64-$DRV.run && sh drv.run --extract-only --target $T/drv >/dev/null\nmkdir -p $T/nvlib; find $T/drv -maxdepth 1 -name \'lib*.so*\' -exec cp {} $T/nvlib/ \\;\ncd $T/nvlib; for f in *.so.$DRV; do b=${f%.$DRV}; ln -sf $f $b.1 2>/dev/null; ln -sf $f $b.0 2>/dev/null; ln -sf $f $b; done; cd $T\ncat > $T/nvidia_icd.json <<J\n{"file_format_version":"1.0.1","ICD":{"library_path":"$T/nvlib/libGLX_nvidia.so.0","api_version":"1.4.312"}}\nJ\nmkdir -p $T/egl; cat > $T/egl/10_nvidia.json <<J\n{"file_format_version":"1.0.0","ICD":{"library_path":"$T/nvlib/libEGL_nvidia.so.0"}}\nJ\napt-get update -qq >/dev/null 2>&1; DEBIAN_FRONTEND=noninteractive apt-get install -y -qq --no-install-recommends libglu1-mesa libxt6t64 libxrandr2 libxinerama1 libxcursor1 libxi6 libvulkan1 libsm6 libice6 libxkbcommon0 libegl1 libgl1 > $W/logs/apt.log 2>&1\n# 2) micromamba\ncurl -sfL https://micro.mamba.pm/api/micromamba/linux-64/latest | tar -xj -C $T bin/micromamba\nMM=$T/bin/micromamba\n( $MM create -y -q -n ros -c robostack-staging -c conda-forge python=3.11 ros-humble-ros-base ros-humble-robot-state-publisher \\\n   ros-humble-cv-bridge ros-humble-tf2-ros ros-humble-image-transport ros-humble-rosidl-default-generators \\\n   colcon-common-extensions cmake make compilers ninja pkg-config yaml-cpp pyzmq pyyaml "numpy<2" scipy > $W/logs/ros_env.log 2>&1\n  echo ros_env_rc=$? >> $W/logs/ros_env.log ) &\nRP=$!\n( $MM create -y -q -n isaac -c conda-forge python=3.11 pip > $W/logs/isaac_env.log 2>&1\n  P=$MAMBA_ROOT_PREFIX/envs/isaac/bin/python\n  $P -m pip install -q torch==2.7.0 torchvision==0.22.0 --index-url https://download.pytorch.org/whl/cu128 >> $W/logs/isaac_env.log 2>&1\n  $P -m pip install -q -U pip "setuptools<70" wheel >> $W/logs/isaac_env.log 2>&1\n  $P -m pip install -q --no-build-isolation flatdict==4.0.1 >> $W/logs/isaac_env.log 2>&1\n  $P -m pip install -q "isaaclab[isaacsim,all]==2.2.0" --extra-index-url https://pypi.nvidia.com >> $W/logs/isaac_env.log 2>&1\n  $P -m pip install -q pyzmq "numpy<2" "packaging==24.2" pyyaml opencv-python-headless >> $W/logs/isaac_env.log 2>&1\n  echo isaac_env_rc=$? >> $W/logs/isaac_env.log ) &\nIP=$!\n# 3) repo copy (dataset is read-only)\nSRC=$(find /kaggle/input -maxdepth 5 -type d -name polygon | head -1); echo SRC=$SRC; ls /kaggle/input; mkdir -p /tmp/nssr_sim && cp -r $SRC/. /tmp/nssr_sim/ ; ln -sfn /tmp/nssr_sim /nssr_sim\nwait $RP; wait $IP\n# 4) bodyctrl_msgs from the deb\'s own interface files\nmkdir -p $T/bc $T/ws/src/bodyctrl_msgs && dpkg-deb -x /tmp/nssr_sim/teleoperation/msgs/ros-humble-bodyctrl-msgs_0.0.1-1_amd64.deb $T/bc\nS=$T/bc/opt/ros/humble/share/bodyctrl_msgs; D=$T/ws/src/bodyctrl_msgs; mkdir -p $D/msg $D/srv\ncp $S/msg/*.msg $D/msg/; cp $S/srv/*.srv $D/srv/; cp $S/package.xml $D/\npython3 - "$D" <<\'PY\'\nimport sys,os,glob;d=sys.argv[1]\nmsgs=sorted(\'msg/\'+os.path.basename(f) for f in glob.glob(d+\'/msg/*.msg\'));srvs=sorted(\'srv/\'+os.path.basename(f) for f in glob.glob(d+\'/srv/*.srv\'))\n# drop Request/Response msgs generated from srv\nmsgs=[m for m in msgs if not (m.endswith(\'_Request.msg\') or m.endswith(\'_Response.msg\'))]\nopen(d+\'/CMakeLists.txt\',\'w\').write("""cmake_minimum_required(VERSION 3.8)\nproject(bodyctrl_msgs)\nfind_package(ament_cmake REQUIRED)\nfind_package(rosidl_default_generators REQUIRED)\nfind_package(std_msgs REQUIRED)\nfind_package(geometry_msgs REQUIRED)\nfind_package(builtin_interfaces REQUIRED)\nfind_package(sensor_msgs REQUIRED)\nrosidl_generate_interfaces(${PROJECT_NAME}\n%s\nDEPENDENCIES std_msgs geometry_msgs builtin_interfaces sensor_msgs)\nament_export_dependencies(rosidl_default_runtime)\nament_package()\n"""%\'\\n\'.join(\'"%s"\'%x for x in msgs+srvs))\nPY\neval "$($MM shell hook -s bash)"; micromamba activate ros\ncd $T/ws && colcon build --cmake-args -DBUILD_TESTING=OFF -DPython3_EXECUTABLE=$(which python) > $W/logs/bodyctrl_build.log 2>&1; echo bodyctrl_rc=$? | tee -a $W/logs/bodyctrl_build.log\nsource $T/ws/install/setup.bash && python -c "from bodyctrl_msgs.msg import CmdSetMotorPosition, MotorStatusMsg; from bodyctrl_msgs.srv import SetSpeed; print(\'bodyctrl import OK\')" | tee -a $W/logs/bodyctrl_build.log\nmicromamba deactivate\n# 5) simulator package (as in docker/run.sh init)\nP=$MAMBA_ROOT_PREFIX/envs/isaac/bin/python\ncd /tmp/nssr_sim/source && $P -m pip install -q --no-deps -e . > $W/logs/nssr_pkg.log 2>&1; $P -c \'import nssr_sim; print("nssr_sim OK")\' >> $W/logs/nssr_pkg.log 2>&1\ndf -h /tmp | tail -1 >> $W/logs/gpu.txt\n', 'run_stage34.sh': '#!/bin/bash\n# Stage 3-4: start sim headless (as start_sim.sh: bridge in ROS python, sim_runner in Isaac python), run check_interfaces.py, dump TF/camera_info.\nset -x\nW=/kaggle/working; T=/tmp/w; export MAMBA_ROOT_PREFIX=$T/mm; MM=$T/bin/micromamba; cd /tmp/nssr_sim\nexport ROS_DOMAIN_ID=146 RMW_IMPLEMENTATION=rmw_fastrtps_cpp ACCEPT_EULA=Y PRIVACY_CONSENT=Y OMNI_KIT_ACCEPT_EULA=YES\nexport FASTRTPS_DEFAULT_PROFILES_FILE=/tmp/nssr_sim/hackathon/docker/fastdds_hack.xml\nexport HACK_TASK=${HACK_TASK:-sort3} HACK_POOL=${HACK_POOL:-3} HACK_SEED=${HACK_SEED:-1} HACK_HEADLESS=1 HACK_RES=${HACK_RES:-1280x720} HACK_RENDER_INTERVAL=3\nexport VK_ICD_FILENAMES=$T/nvidia_icd.json VK_DRIVER_FILES=$T/nvidia_icd.json __EGL_VENDOR_LIBRARY_DIRS=$T/egl\nISAAC_LD=$T/nvlib\nrosenv(){ ( eval "$($MM shell hook -s bash)"; micromamba activate ros; source $T/ws/install/setup.bash; "$@" ); }\n# bridge (ROS side)\nrosenv python teleoperation/bridges/ros2_zmq_bridge.py > $W/logs/bridge.log 2>&1 &\nBR=$!; sleep 3\nKIT="--/rtx/raytracing/fractionalCutoutOpacity=true --/rtx/pathtracing/fractionalCutoutOpacity=true --/rtx/translucency/maxRefractionBounces=4 --/app/runLoops/main/rateLimitEnabled=false --/app/renderer/resolution/width=${HACK_RES%x*} --/app/renderer/resolution/height=${HACK_RES#*x}"\nexport HACK_KIT_ARGS="$KIT"\nLD_LIBRARY_PATH=$ISAAC_LD:$LD_LIBRARY_PATH $MAMBA_ROOT_PREFIX/envs/isaac/bin/python scripts/sim_runner.py --task NSSRSim-TiangongPro-Parlor-v0 --enable_cameras --num_envs 1 \\\n  --perf_stats --step_hz 100 --headless --device cpu > $W/logs/sim_${HACK_TASK}_p${HACK_POOL}_s${HACK_SEED}.log 2>&1 &\nSIM=$!\n# wait for /sim/task\nfor i in $(seq 1 120); do\n  if rosenv timeout 5 ros2 topic echo --once /sim/task std_msgs/msg/String > $W/logs/sim_task.txt 2>/dev/null; then break; fi\n  kill -0 $SIM 2>/dev/null || break; sleep 5\ndone\necho "waited $((i*10))s"; cat $W/logs/sim_task.txt\nrosenv timeout 600 python hackathon/tools/check_interfaces.py > $W/logs/check_interfaces.log 2>&1; echo check_rc=$? >> $W/logs/check_interfaces.log\nrosenv timeout 20 ros2 topic echo --once /cam_head/color/camera_info > $W/logs/caminfo_head_color.txt 2>&1\nrosenv timeout 20 ros2 topic echo --once /cam_head/depth/camera_info > $W/logs/caminfo_head_depth.txt 2>&1\nrosenv timeout 20 ros2 topic echo --once /cam_torso/color/camera_info > $W/logs/caminfo_torso_color.txt 2>&1\nrosenv timeout 30 ros2 run tf2_ros tf2_echo pelvis camera_head_link > $W/logs/tf_pelvis_camhead.txt 2>&1\nrosenv timeout 20 ros2 topic echo --once /tf_static > $W/logs/tf_static.txt 2>&1\nrosenv timeout 20 ros2 topic list -t > $W/logs/topics.txt 2>&1\nrosenv timeout 20 ros2 topic echo --once /joint_states > $W/logs/joint_states.txt 2>&1\nrosenv timeout 60 python /kaggle/working/grab_frames.py > $W/logs/grab.log 2>&1\nkill -INT $SIM; sleep 10; kill $BR; pkill -f sim_node.py; pkill -f camera_bridge.py; pkill -f robot_state_publisher; pkill -9 -f sim_runner.py\n', 'grab_frames.py': "# save one RGB + depth frame from each camera with camera_info (sensor data only) for offline calibration/perception\nimport rclpy,numpy as np,json,time\nfrom rclpy.node import Node\nfrom sensor_msgs.msg import Image,CameraInfo\nfrom rclpy.qos import qos_profile_sensor_data\nrclpy.init();n=Node('grab');got={}\ndef cb(k):\n    def f(m):\n        if k in got:return\n        if isinstance(m,CameraInfo):got[k]=dict(K=list(m.k),w=m.width,h=m.height,frame=m.header.frame_id,D=list(m.d))\n        else:\n            dt={'rgb8':np.uint8,'bgr8':np.uint8,'16UC1':np.uint16,'32FC1':np.float32}.get(m.encoding,np.uint8)\n            a=np.frombuffer(bytes(m.data),dt);np.save(f'/kaggle/working/{k}.npy',a.reshape(m.height,m.width,-1));got[k]=dict(enc=m.encoding,frame=m.header.frame_id,stamp=m.header.stamp.sec+m.header.stamp.nanosec*1e-9)\n    return f\nfor cam in('cam_head','cam_torso'):\n    for s in('color','depth'):\n        n.create_subscription(Image,f'/{cam}/{s}/image_raw',cb(f'{cam}_{s}'),qos_profile_sensor_data)\n        n.create_subscription(CameraInfo,f'/{cam}/{s}/camera_info',cb(f'{cam}_{s}_info'),10)\nt=time.time()\nwhile time.time()-t<40 and len(got)<8:rclpy.spin_once(n,timeout_sec=.2)\njson.dump(got,open('/kaggle/working/frames.json','w'),indent=1);print(sorted(got))\n", 'run_sort.sh': '#!/bin/bash\n# Pool-3 sorting runs: start sim once per task variant, then per layout: randomize(seed) -> run.sh (fresh process) -> /sim/task/check.\nW=/kaggle/working; T=/tmp/w; export MAMBA_ROOT_PREFIX=$T/mm; MM=$T/bin/micromamba; cd /tmp/nssr_sim\nexport ROS_DOMAIN_ID=146 RMW_IMPLEMENTATION=rmw_fastrtps_cpp ACCEPT_EULA=Y PRIVACY_CONSENT=Y OMNI_KIT_ACCEPT_EULA=YES\nexport FASTRTPS_DEFAULT_PROFILES_FILE=/tmp/nssr_sim/hackathon/docker/fastdds_hack.xml\nexport VK_ICD_FILENAMES=$T/nvidia_icd.json VK_DRIVER_FILES=$T/nvidia_icd.json __EGL_VENDOR_LIBRARY_DIRS=$T/egl\nrosenv(){ ( eval "$($MM shell hook -s bash)"; micromamba activate ros; source $T/ws/install/setup.bash; [ -f /tmp/sol/install/setup.bash ] && source /tmp/sol/install/setup.bash; "$@" ); }\n# build solution as the organisers do (colcon build in /solution copy)\nrm -rf /tmp/sol; cp -r /kaggle/working/solution /tmp/sol; (cd /tmp/sol && rosenv colcon build > $W/logs/sol_build.log 2>&1; echo sol_build_rc=$? >> $W/logs/sol_build.log)\nfor TASK in ${TASKS:-sort2 sort3}; do\n export HACK_TASK=$TASK HACK_POOL=${HACK_POOL:-3} HACK_SEED=${SEED0:-100} HACK_HEADLESS=1 HACK_RES=1280x720 HACK_RENDER_INTERVAL=3\n export HACK_KIT_ARGS="--/rtx/raytracing/fractionalCutoutOpacity=true --/rtx/pathtracing/fractionalCutoutOpacity=true --/rtx/translucency/maxRefractionBounces=4 --/app/runLoops/main/rateLimitEnabled=false --/app/renderer/resolution/width=1280 --/app/renderer/resolution/height=720"\n rosenv python teleoperation/bridges/ros2_zmq_bridge.py > $W/logs/bridge_$TASK.log 2>&1 & BR=$!; sleep 3\n LD_LIBRARY_PATH=$T/nvlib:$LD_LIBRARY_PATH $MAMBA_ROOT_PREFIX/envs/isaac/bin/python scripts/sim_runner.py --task NSSRSim-TiangongPro-Parlor-v0 --enable_cameras --num_envs 1 --perf_stats --step_hz 100 --headless --device cpu > $W/logs/sim_$TASK.log 2>&1 & SIM=$!\n for i in $(seq 1 120); do rosenv timeout 5 ros2 topic echo --once --qos-durability transient_local /sim/task std_msgs/msg/String >/dev/null 2>&1 && break; sleep 5; done\n for k in $(seq 1 ${NLAYOUTS:-5}); do\n   S=$((SEED0+k)); [ $k -gt 1 ] && { rosenv ros2 topic pub --once /sim/objects/randomize std_msgs/msg/Int32 "{data: $S}" >/dev/null 2>&1; sleep 15; }\n   rosenv python /kaggle/working/score.py start > $W/logs/t0_${TASK}_$S.txt 2>&1\n   ( cd /tmp/sol && rosenv timeout ${RUNTO:-900} bash run.sh ) > $W/logs/run_${TASK}_$S.log 2>&1\n   rosenv python /kaggle/working/score.py check $TASK $S >> $W/results.jsonl 2>> $W/logs/score_err.log\n   tail -1 $W/results.jsonl\n done\n kill -INT $SIM; sleep 10; kill $BR; pkill -f sim_node.py; pkill -f camera_bridge.py; pkill -f robot_state_publisher; pkill -9 -f sim_runner.py; sleep 5\ndone\n', 'score.py': "# debug-only scoring via /sim/task/check (disabled at final evaluation); also measures sim time\nimport rclpy,json,sys,time\nfrom rclpy.node import Node\nfrom std_msgs.msg import Int32,String\nfrom rosgraph_msgs.msg import Clock\nrclpy.init();n=Node('score');res={};clk={}\nn.create_subscription(String,'/sim/task/result',lambda m:res.update(json.loads(m.data)),10)\nn.create_subscription(Clock,'/clock',lambda m:clk.update(t=m.clock.sec+m.clock.nanosec*1e-9),10)\np=n.create_publisher(Int32,'/sim/task/check',10)\nt=time.time()\nwhile 't' not in clk and time.time()-t<20:rclpy.spin_once(n,timeout_sec=.1)\nif sys.argv[1]=='start':print(json.dumps({'sim_t':clk.get('t')}));sys.exit()\nfor _ in range(30):\n    p.publish(Int32(data=1));rclpy.spin_once(n,timeout_sec=.3)\n    if res:break\nr=res;sc=10*r.get('in_right_tray',0)-10*r.get('in_wrong_tray',0)\nprint(json.dumps({'task':sys.argv[2],'seed':int(sys.argv[3]),'score_lb':sc,'sim_t_end':clk.get('t'),**{k:r.get(k) for k in('in_right_tray','in_wrong_tray','not_in_tray','total')},'objects':r.get('objects')}))\n"}
for k,v in F.items():open('/kaggle/working/'+k,'w').write(v)
tarfile.open(fileobj=io.BytesIO(base64.b64decode('')),mode='r:gz').extractall('/kaggle/working')
os.environ.update({'TASKS': 'sort3', 'NLAYOUTS': '3', 'SEED0': '100'})
t=time.time()
def step(name,script,to):
    r=subprocess.run(['bash','/kaggle/working/'+script],stdout=open('/kaggle/working/'+name+'.log','w'),stderr=subprocess.STDOUT,timeout=to)
    print(name,'rc',r.returncode,round(time.time()-t),flush=True)
for st in ['setup', 'stage34', 'sort']:
    if st=='setup':
        step('setup','setup_env.sh',5400)
        for f in ['gpu.txt','bodyctrl_build.log','nssr_pkg.log','isaac_env.log']:
            try:print(f,open('/kaggle/working/logs/'+f).read()[-1200:],flush=True)
            except Exception as e:print(f,e)
    if st=='stage34':
        step('stage34','run_stage34.sh',3000)
        try:print(open('/kaggle/working/logs/check_interfaces.log').read()[-5000:],flush=True)
        except Exception as e:print(e)
    if st=='sort':
        step('sort','run_sort.sh',30000)
        try:print(open('/kaggle/working/results.jsonl').read()[-5000:],flush=True)
        except Exception as e:print(e)
